#include <bits/stdc++.h>
using namespace std;

class Solution {
 vector<long long> dijkstra(int src,const vector<vector<pair<int,int>>>& g){const long long INF=LLONG_MAX/4;int n=g.size();vector<long long>d(n,INF);
  priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> pq;d[src]=0;pq.push({0,src});
  while(!pq.empty()){auto cur=pq.top();pq.pop();long long dist=cur.first;int u=cur.second;if(dist!=d[u])continue;
   for(auto e:g[u])if(dist+e.second<d[e.first]){d[e.first]=dist+e.second;pq.push({d[e.first],e.first});}
  }return d;
 }
 public:
 long long minimumWeight(int n,vector<vector<int>>& edges,int src1,int src2,int dest){vector<vector<pair<int,int>>> g(n),rg(n);
  for(auto&e:edges){g[e[0]].push_back({e[1],e[2]});rg[e[1]].push_back({e[0],e[2]});}
  auto a=dijkstra(src1,g),b=dijkstra(src2,g),c=dijkstra(dest,rg);long long ans=LLONG_MAX/4;
  for(int i=0;i<n;++i)if(a[i]<LLONG_MAX/4&&b[i]<LLONG_MAX/4&&c[i]<LLONG_MAX/4)ans=min(ans,a[i]+b[i]+c[i]);return ans==LLONG_MAX/4?-1:ans;
 }
};
